  subroutine check_column_water_flux(this, label, nmiss)
    type(column_water_flux), intent(in), target :: this
    character(len=*), intent(in) :: label
    integer, intent(inout) :: nmiss
    integer :: i_
#ifdef _OPENACC
    if (associated(this%qflx_prec_grnd)) call dd_miss(acc_is_present(this%qflx_prec_grnd), label, 'qflx_prec_grnd', &
         nmiss)
    if (associated(this%qflx_rain_grnd)) call dd_miss(acc_is_present(this%qflx_rain_grnd), label, 'qflx_rain_grnd', &
         nmiss)
    if (associated(this%qflx_snow_grnd)) call dd_miss(acc_is_present(this%qflx_snow_grnd), label, 'qflx_snow_grnd', &
         nmiss)
    if (associated(this%qflx_sub_snow)) call dd_miss(acc_is_present(this%qflx_sub_snow), label, 'qflx_sub_snow', nmiss)
    if (associated(this%qflx_sub_snow_vol)) call dd_miss(acc_is_present(this%qflx_sub_snow_vol), label, &
         'qflx_sub_snow_vol', nmiss)
    if (associated(this%qflx_evap_soi)) call dd_miss(acc_is_present(this%qflx_evap_soi), label, 'qflx_evap_soi', nmiss)
    if (associated(this%qflx_evap_veg)) call dd_miss(acc_is_present(this%qflx_evap_veg), label, 'qflx_evap_veg', nmiss)
    if (associated(this%qflx_evap_can)) call dd_miss(acc_is_present(this%qflx_evap_can), label, 'qflx_evap_can', nmiss)
    if (associated(this%qflx_evap_tot)) call dd_miss(acc_is_present(this%qflx_evap_tot), label, 'qflx_evap_tot', nmiss)
    if (associated(this%qflx_evap_grnd)) call dd_miss(acc_is_present(this%qflx_evap_grnd), label, 'qflx_evap_grnd', &
         nmiss)
    if (associated(this%qflx_snwcp_liq)) call dd_miss(acc_is_present(this%qflx_snwcp_liq), label, 'qflx_snwcp_liq', &
         nmiss)
    if (associated(this%qflx_snwcp_ice)) call dd_miss(acc_is_present(this%qflx_snwcp_ice), label, 'qflx_snwcp_ice', &
         nmiss)
    if (associated(this%qflx_ice_runoff_xs)) call dd_miss(acc_is_present(this%qflx_ice_runoff_xs), label, &
         'qflx_ice_runoff_xs', nmiss)
    if (associated(this%qflx_tran_veg)) call dd_miss(acc_is_present(this%qflx_tran_veg), label, 'qflx_tran_veg', nmiss)
